/// Operators that are **lazy in their right operand**.
///
/// Separate from [`Operators`] because their meaning is the one thing
/// that genuinely differs between an interpreter and a compiler:
/// short-circuiting is a *decision* to one and *control flow* to the
/// other.
///
/// **You almost certainly do not implement this.** `nh_handlers!` writes
/// the interpreter's version from your [`Values`] impl. Write it yourself
/// only if you are emitting code rather than producing values, and then
/// say so:
///
/// ```ignore
/// nh_handlers!(Interp, without short_circuit);
/// ```
pub trait ShortCircuit: Semantics {

    /// `||` — **lazy in its right operand**.
    ///
    /// `rhs` is unevaluated. Running it is what evaluates it; not
    /// running it is what makes this short-circuit.
    ///
    /// An interpreter gets this written for it by `nh_handlers!`. A
    /// compiler writes it, emitting a jump — short-circuiting is
    /// control flow to it, not a decision.
    fn or_else(
        &mut self,
        lhs: Self::Out,
        rhs: Rc<Expr>,
        cx: &mut Ctx,
    ) -> Result<Self::Out>
    where
        Self: Handlers + Sized;

    /// `&&` — **lazy in its right operand**.
    ///
    /// `rhs` is unevaluated. Running it is what evaluates it; not
    /// running it is what makes this short-circuit.
    ///
    /// An interpreter gets this written for it by `nh_handlers!`. A
    /// compiler writes it, emitting a jump — short-circuiting is
    /// control flow to it, not a decision.
    fn and_then(
        &mut self,
        lhs: Self::Out,
        rhs: Rc<Expr>,
        cx: &mut Ctx,
    ) -> Result<Self::Out>
    where
        Self: Handlers + Sized;
}

/// Operator semantics.
///
/// Every method is defaulted to an `unsupported` error, so a language
/// implements only the operators it actually has and gets the rest of the
/// table's parsing, precedence, and short-circuiting for free (§6.4).
pub trait Operators: ShortCircuit {

    /// `==`
    fn compare(&mut self, lhs: Self::Out, op: CompareOp, rhs: Self::Out) -> Result<Self::Out> {
        let _ = (lhs, rhs);
        Err(Error::unsupported("compare"))
    }

    /// `+`
    fn add(&mut self, lhs: Self::Out, rhs: Self::Out) -> Result<Self::Out> {
        let _ = (lhs, rhs);
        Err(Error::unsupported("add"))
    }

    /// `-`
    fn sub(&mut self, lhs: Self::Out, rhs: Self::Out) -> Result<Self::Out> {
        let _ = (lhs, rhs);
        Err(Error::unsupported("sub"))
    }

    /// `*`
    fn mul(&mut self, lhs: Self::Out, rhs: Self::Out) -> Result<Self::Out> {
        let _ = (lhs, rhs);
        Err(Error::unsupported("mul"))
    }

    /// `/`
    fn div(&mut self, lhs: Self::Out, rhs: Self::Out) -> Result<Self::Out> {
        let _ = (lhs, rhs);
        Err(Error::unsupported("div"))
    }

    /// `%`
    fn rem(&mut self, lhs: Self::Out, rhs: Self::Out) -> Result<Self::Out> {
        let _ = (lhs, rhs);
        Err(Error::unsupported("rem"))
    }

    /// `**`
    fn pow(&mut self, lhs: Self::Out, rhs: Self::Out) -> Result<Self::Out> {
        let _ = (lhs, rhs);
        Err(Error::unsupported("pow"))
    }

    /// `!` (prefix).
    fn not(&mut self, operand: Self::Out) -> Result<Self::Out> {
        let _ = operand;
        Err(Error::unsupported("not"))
    }

    /// `-` (prefix).
    fn neg(&mut self, operand: Self::Out) -> Result<Self::Out> {
        let _ = operand;
        Err(Error::unsupported("neg"))
    }

    /// Stores `value` at `place`.
    ///
    /// `place` arrives with its parts already evaluated, so a subscript
    /// with a side effect ran exactly once before this was called.
    fn assign(
        &mut self,
        place: Place<'_, Self::Out>,
        value: Self::Out,
    ) -> Result<Self::Out> {
        let _ = (place, value);
        Err(Error::unsupported("assignment"))
    }

    /// Reads the current value at `place`, for compound assignment.
    fn place_read(&mut self, place: &Place<'_, Self::Out>) -> Result<Self::Out> {
        let _ = place;
        Err(Error::unsupported("reading an assignment target"))
    }

    /// `+=`, `-=`, and friends.
    ///
    /// Defaulted: read the place, apply the operator's arithmetic role,
    /// store the result. Implement `assign` and `place_read` and this
    /// works for the whole family.
    fn compound_assign(
        &mut self,
        place: Place<'_, Self::Out>,
        op: AssignOp,
        rhs: Self::Out,
    ) -> Result<Self::Out> {
        let current = self.place_read(&place)?;
        let updated = match op {
            AssignOp::PlusEq => self.add(current, rhs)?,
            AssignOp::MinusEq => self.sub(current, rhs)?,
            // `=` is plain assignment: the old value is discarded.
            AssignOp::Eq => rhs,
        };
        self.assign(place, updated)
    }
}

/// One **required** method per labelled alternative.
///
/// Each takes the alternative's bindings, already evaluated — the
/// generated evaluator does the walking. Nothing is defaulted: adding
/// an alternative to the grammar must break the build until a handler
/// exists.
pub trait Handlers: Operators + Sized {

    /// `program` — from `rule program = SOI stmts:stmt* EOI -> doc`.
    /// * `stmts` — the value of the `stmt` rule, already evaluated (repeated in the grammar; items that failed and were already reported are omitted)
    fn program(&mut self, stmts: Vec<Self::Out>, cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_bind` — from `rule stmt = "let" name:IDENT "=" value:expr ";" -> bind`.
    /// * `name` — the text of the `IDENT` token
    /// * `value` — the value of the `expr` rule, already evaluated
    fn stmt_bind(&mut self, name: &str, value: Self::Out, cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_iff` — from `rule stmt = "if" cond:expr "then" lazy body:stmt -> iff`.
    /// * `cond` — the value of the `expr` rule, already evaluated
    /// * `body` — the `stmt` rule, **unevaluated** — `.eval(host, cx)?` runs it
    fn stmt_iff(&mut self, cond: Self::Out, body: &Rc<Stmt>, cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_eval` — from `rule stmt = value:expr ";" -> eval`.
    /// * `value` — the value of the `expr` rule, already evaluated
    fn stmt_eval(&mut self, value: Self::Out, cx: &mut Ctx) -> Result<Self::Out>;

    /// `primary_num` — from `rule primary = digits:NUMBER -> num`.
    /// * `digits` — the text of the `NUMBER` token
    fn primary_num(&mut self, digits: &str, cx: &mut Ctx) -> Result<Self::Out>;

    /// `primary_elem` — from `rule primary = name:IDENT "[" index:expr "]" -> elem place`.
    /// * `name` — the text of the `IDENT` token
    /// * `index` — the value of the `expr` rule, already evaluated
    fn primary_elem(&mut self, name: &str, index: Self::Out, cx: &mut Ctx) -> Result<Self::Out>;

    /// `primary_yes` — from `rule primary = "true" -> yes`.
    fn primary_yes(&mut self, cx: &mut Ctx) -> Result<Self::Out>;

    /// `primary_no` — from `rule primary = "false" -> no`.
    fn primary_no(&mut self, cx: &mut Ctx) -> Result<Self::Out>;

    /// `primary_trace` — from `rule primary = "trace" "(" inner:expr ")" -> trace`.
    /// * `inner` — the value of the `expr` rule, already evaluated
    fn primary_trace(&mut self, inner: Self::Out, cx: &mut Ctx) -> Result<Self::Out>;

    /// `primary_var` — from `rule primary = name:IDENT -> var place`.
    /// * `name` — the text of the `IDENT` token
    fn primary_var(&mut self, name: &str, cx: &mut Ctx) -> Result<Self::Out>;
}

