// ---------------------------------------------------------------------------
// The operator driver
// ---------------------------------------------------------------------------

/// Precedence, fixity, and associativity per operator rule.
///
/// Precedences come from the resolved table's tier order, so this and
/// `nh explain` agree by construction.
pub fn op_info(rule: Rule) -> Option<OpInfo> {
    let info = |precedence, fixity, assoc| Some(OpInfo { precedence, fixity, assoc });
    match rule {
        Rule::nh_op_amp_amp => info(4, Fixity::Infix, Assoc::Left),
        Rule::nh_op_bang => info(9, Fixity::Prefix, Assoc::Right),
        Rule::nh_op_bang_eq => info(5, Fixity::Infix, Assoc::Left),
        Rule::nh_op_eq => info(2, Fixity::Infix, Assoc::Right),
        Rule::nh_op_eq_eq => info(5, Fixity::Infix, Assoc::Left),
        Rule::nh_op_gt => info(5, Fixity::Infix, Assoc::Left),
        Rule::nh_op_gt_eq => info(5, Fixity::Infix, Assoc::Left),
        Rule::nh_op_lt => info(5, Fixity::Infix, Assoc::Left),
        Rule::nh_op_lt_eq => info(5, Fixity::Infix, Assoc::Left),
        Rule::nh_op_minus => info(6, Fixity::Infix, Assoc::Left),
        Rule::nh_op_minus_eq => info(1, Fixity::Infix, Assoc::Right),
        Rule::nh_op_percent => info(7, Fixity::Infix, Assoc::Left),
        Rule::nh_op_pipe_pipe => info(3, Fixity::Infix, Assoc::Left),
        Rule::nh_op_plus => info(6, Fixity::Infix, Assoc::Left),
        Rule::nh_op_plus_eq => info(1, Fixity::Infix, Assoc::Right),
        Rule::nh_op_slash => info(7, Fixity::Infix, Assoc::Left),
        Rule::nh_op_star => info(7, Fixity::Infix, Assoc::Left),
        Rule::nh_op_star_star => info(8, Fixity::Infix, Assoc::Right),
        _ => None,
    }
}

/// The prefix reading of an operator rule.
///
/// A spelling like `-` is both `sub` and `neg`, and the lowerer emits one
/// rule for it. The builder consults this where an operand is expected and
/// [`op_info`] everywhere else.
pub fn prefix_info(rule: Rule) -> Option<OpInfo> {
    let info = |precedence| Some(OpInfo {
        precedence,
        fixity: Fixity::Prefix,
        assoc: Assoc::Right,
    });
    match rule {
        Rule::nh_op_bang => info(9),
        Rule::nh_op_minus => info(9),
        _ => None,
    }
}

/// Evaluates a folded expression.
///
/// The folding already happened, once, when the AST was built — so a
/// loop that re-tests its condition is not re-folding it every pass.
pub fn eval_expr<H: Handlers>(
    host: &mut H,
    node: &Expr,
    cx: &mut Ctx,
) -> Result<H::Out> {
    match node {
        Expr::Atom(a) => eval_primary(host, a, cx),

        Expr::Prefix { op, operand, .. } => {
            let value = eval_expr(host, operand, cx)?;
            match op {
                Rule::nh_op_bang => host.not(value),
                Rule::nh_op_minus => host.neg(value),
                other => Err(Error::runtime(format!(
                    "`{other:?}` is not a prefix operator"
                ))),
            }
        }
        Expr::Postfix { op, .. } => Err(Error::runtime(format!(
            "`{op:?}` is not a postfix operator"
        ))),
        Expr::Infix { lhs, op, rhs, .. } => match op {
            &Rule::nh_op_plus_eq => {
                // The target is RESOLVED, not evaluated as a value, and
                // its parts are computed exactly once.
                let place = resolve_place(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.compound_assign(place, AssignOp::PlusEq, right)
            }
            &Rule::nh_op_minus_eq => {
                // The target is RESOLVED, not evaluated as a value, and
                // its parts are computed exactly once.
                let place = resolve_place(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.compound_assign(place, AssignOp::MinusEq, right)
            }
            &Rule::nh_op_eq => {
                // The target is RESOLVED, not evaluated as a value, and
                // its parts are computed exactly once.
                let place = resolve_place(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.assign(place, right)
            }
            &Rule::nh_op_pipe_pipe => {
                let left = eval_expr(host, lhs, cx)?;
                host.or_else(left, rhs.clone(), cx)
            }
            &Rule::nh_op_amp_amp => {
                let left = eval_expr(host, lhs, cx)?;
                host.and_then(left, rhs.clone(), cx)
            }
            &Rule::nh_op_eq_eq => {
                let left = eval_expr(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.compare(left, CompareOp::EqEq, right)
            }
            &Rule::nh_op_bang_eq => {
                let left = eval_expr(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.compare(left, CompareOp::BangEq, right)
            }
            &Rule::nh_op_lt_eq => {
                let left = eval_expr(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.compare(left, CompareOp::LtEq, right)
            }
            &Rule::nh_op_gt_eq => {
                let left = eval_expr(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.compare(left, CompareOp::GtEq, right)
            }
            &Rule::nh_op_lt => {
                let left = eval_expr(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.compare(left, CompareOp::Lt, right)
            }
            &Rule::nh_op_gt => {
                let left = eval_expr(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.compare(left, CompareOp::Gt, right)
            }
            &Rule::nh_op_plus => {
                let left = eval_expr(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.add(left, right)
            }
            &Rule::nh_op_minus => {
                let left = eval_expr(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.sub(left, right)
            }
            &Rule::nh_op_star => {
                let left = eval_expr(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.mul(left, right)
            }
            &Rule::nh_op_slash => {
                let left = eval_expr(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.div(left, right)
            }
            &Rule::nh_op_percent => {
                let left = eval_expr(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.rem(left, right)
            }
            &Rule::nh_op_star_star => {
                let left = eval_expr(host, lhs, cx)?;
                let right = eval_expr(host, rhs, cx)?;
                host.pow(left, right)
            }
            other => Err(Error::runtime(format!(
                "`{other:?}` is not an infix operator"
            ))),
        },
    }
}

impl Eval for Expr {
    fn eval<H: Handlers>(&self, host: &mut H, cx: &mut Ctx) -> Result<H::Out> {
        eval_expr(host, self, cx)
    }
}

/// Writes the delegating `Handlers` impl for your type.
///
/// ```ignore
/// nh_handlers!(Interp);
/// ```
///
/// Each method body does nothing but call into `$crate::handlers::<alternative>::run`,
/// so every handler is its own small file and the trait's exhaustiveness
/// still guarantees none is missing.
///
/// It also writes your `ShortCircuit` impl — the standard
/// short-circuit bodies, built on the `truthy` you gave to
/// [`Values`]. That is not a choice anybody makes, so you are not
/// asked to make it.
///
/// A host that emits code rather than producing values has no
/// `truthy` to build them on. It says so, and writes its own:
///
/// ```ignore
/// nh_handlers!(Compiler, without short_circuit);
/// ```
#[macro_export]
macro_rules! nh_handlers {
    ($host:ty) => {
        impl $crate::generated::dispatch::Handlers for $host {
            fn program(
                &mut self,
                stmts: Vec<<Self as $crate::generated::dispatch::Semantics>::Out>,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::program::run(self, stmts, cx)
            }
            fn stmt_bind(
                &mut self,
                name: &str,
                value: <Self as $crate::generated::dispatch::Semantics>::Out,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::stmt_bind::run(self, name, value, cx)
            }
            fn stmt_iff(
                &mut self,
                cond: <Self as $crate::generated::dispatch::Semantics>::Out,
                body: &::std::rc::Rc<$crate::generated::ast::Stmt>,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::stmt_iff::run(self, cond, body, cx)
            }
            fn stmt_eval(
                &mut self,
                value: <Self as $crate::generated::dispatch::Semantics>::Out,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::stmt_eval::run(self, value, cx)
            }
            fn primary_num(
                &mut self,
                digits: &str,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::primary_num::run(self, digits, cx)
            }
            fn primary_elem(
                &mut self,
                name: &str,
                index: <Self as $crate::generated::dispatch::Semantics>::Out,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::primary_elem::run(self, name, index, cx)
            }
            fn primary_yes(
                &mut self,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::primary_yes::run(self, cx)
            }
            fn primary_no(
                &mut self,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::primary_no::run(self, cx)
            }
            fn primary_trace(
                &mut self,
                inner: <Self as $crate::generated::dispatch::Semantics>::Out,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::primary_trace::run(self, inner, cx)
            }
            fn primary_var(
                &mut self,
                name: &str,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::primary_var::run(self, name, cx)
            }
        }
        impl $crate::generated::dispatch::ShortCircuit for $host {
            fn or_else(
                &mut self,
                lhs: <Self as $crate::generated::dispatch::Semantics>::Out,
                rhs: ::std::rc::Rc<$crate::generated::ast::Expr>,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<
                <Self as $crate::generated::dispatch::Semantics>::Out,
            > {
                use $crate::generated::dispatch::{Eval, Values};
                if self.truthy(&lhs) {
                    return Ok(lhs);
                }
                rhs.eval(self, cx)
            }
            fn and_then(
                &mut self,
                lhs: <Self as $crate::generated::dispatch::Semantics>::Out,
                rhs: ::std::rc::Rc<$crate::generated::ast::Expr>,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<
                <Self as $crate::generated::dispatch::Semantics>::Out,
            > {
                use $crate::generated::dispatch::{Eval, Values};
                if !self.truthy(&lhs) {
                    return Ok(lhs);
                }
                rhs.eval(self, cx)
            }
        }
    };
    ($host:ty, without short_circuit) => {
        impl $crate::generated::dispatch::Handlers for $host {
            fn program(
                &mut self,
                stmts: Vec<<Self as $crate::generated::dispatch::Semantics>::Out>,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::program::run(self, stmts, cx)
            }
            fn stmt_bind(
                &mut self,
                name: &str,
                value: <Self as $crate::generated::dispatch::Semantics>::Out,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::stmt_bind::run(self, name, value, cx)
            }
            fn stmt_iff(
                &mut self,
                cond: <Self as $crate::generated::dispatch::Semantics>::Out,
                body: &::std::rc::Rc<$crate::generated::ast::Stmt>,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::stmt_iff::run(self, cond, body, cx)
            }
            fn stmt_eval(
                &mut self,
                value: <Self as $crate::generated::dispatch::Semantics>::Out,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::stmt_eval::run(self, value, cx)
            }
            fn primary_num(
                &mut self,
                digits: &str,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::primary_num::run(self, digits, cx)
            }
            fn primary_elem(
                &mut self,
                name: &str,
                index: <Self as $crate::generated::dispatch::Semantics>::Out,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::primary_elem::run(self, name, index, cx)
            }
            fn primary_yes(
                &mut self,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::primary_yes::run(self, cx)
            }
            fn primary_no(
                &mut self,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::primary_no::run(self, cx)
            }
            fn primary_trace(
                &mut self,
                inner: <Self as $crate::generated::dispatch::Semantics>::Out,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::primary_trace::run(self, inner, cx)
            }
            fn primary_var(
                &mut self,
                name: &str,
                cx: &mut ::nh_runtime::Ctx,
            ) -> ::nh_runtime::Result<<Self as $crate::generated::dispatch::Semantics>::Out> {
                $crate::handlers::primary_var::run(self, name, cx)
            }
        }
    };
}

